CREATE TRIGGER RefCusProfileQuestion_Version_Create
	ON RefCusProfileQuestion
	FOR INSERT
	AS
	INSERT RefDbVersionControl (RVC_ParentPK, RVC_ParentCode)
	SELECT XQ2_PK, 'XQ2'
	FROM inserted
GO
CREATE TRIGGER RefCusProfileQuestion_Version_Update
	ON RefCusProfileQuestion
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON XQ2_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
